entries[70177] = { ["name"] = "Schematic: Flintlocke's Woodchucker", ["text"] = "Binds when picked up\nRequires Engineering (515)\nUse: Teaches you how to make Flintlocke's Woodchucker.\nSell Price:\nFlintlocke's Woodchucker\nClasses: Hunter\nRequires Level 80\nUse: Attaches a permanent device to a bow or gun that sometimes launches a rabid critter, dealing additional damage to the target and increasing your Agility by 300 for 10 sec.\n\nAttaching this device to a ranged weapon causes it to become soulbound.\n\"'slike a wee angry bullet wit' teeth, son.\"\nSell Price:\nRequires Hardened Elementium Bar , Electrified Ether (4), Handful of Obsidium Bolts (5), Dream Emerald (2)" }
